package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
	"strconv"
	"strings"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	first := true
	for scanner.Scan() {
		line := scanner.Text()
		if first {
			first = false
			continue
		}
		fields := strings.Fields(line)
		arr := make([]int, 0, len(fields))
		for _, f := range fields {
			num, err := strconv.Atoi(f)
			if err == nil {
				arr = append(arr, num)
			}
		}
		sort.Ints(arr)
		ans := 0
		prev := -1
		for _, v := range arr {
			if v != 0 && v != prev {
				ans++
				prev = v
			}
		}
		fmt.Println(ans)
	}
}

